pm.test("El producto se crea correctamente", function () {
    pm.response.to.have.status(201);
});

pm.test("La respuesta contiene un mensaje de éxito", function () {
    const respuesta = pm.response.json();
    pm.expect(respuesta.mensaje).to.eql("Producto creado correctamente");
});

pm.test("El producto creado contiene sus datos", function () {
    const respuesta = pm.response.json();

    pm.expect(respuesta.producto).to.have.property("nombre");
    pm.expect(respuesta.producto).to.have.property("precio");
    pm.expect(respuesta.producto).to.have.property("stock");
});

// Guardar automáticamente el ID para utilizarlo en el carrito.
const respuesta = pm.response.json();

pm.collectionVariables.set(
    "productoId",
    respuesta.producto._id
);

pm.test("La consulta de productos responde correctamente", function () {
    pm.response.to.have.status(200);
});

pm.test("La respuesta contiene una lista de productos", function () {
    const respuesta = pm.response.json();

    pm.expect(respuesta).to.have.property("productos");
    pm.expect(respuesta.productos).to.be.an("array");
});

pm.test("La respuesta contiene el total de productos", function () {
    const respuesta = pm.response.json();

    pm.expect(respuesta.total).to.be.a("number");
});

pm.test("El producto se agrega correctamente al carrito", function () {
    pm.response.to.have.status(200);
});

pm.test("La respuesta contiene un mensaje de éxito", function () {
    const respuesta = pm.response.json();

    pm.expect(respuesta.mensaje).to.eql(
        "Producto agregado al carrito correctamente"
    );
});

pm.test("El carrito contiene el producto agregado", function () {
    const respuesta = pm.response.json();

    pm.expect(respuesta.carrito.items).to.be.an("array");
    pm.expect(respuesta.carrito.items.length).to.be.above(0);
});

pm.test("La consulta del carrito responde correctamente", function () {
    pm.response.to.have.status(200);
});

pm.test("La respuesta contiene los productos del carrito", function () {
    const respuesta = pm.response.json();

    pm.expect(respuesta).to.have.property("items");
    pm.expect(respuesta.items).to.be.an("array");
});

pm.test("Los productos del carrito tienen una cantidad válida", function () {
    const respuesta = pm.response.json();

    respuesta.items.forEach(function (item) {
        pm.expect(item.cantidad).to.be.a("number");
        pm.expect(item.cantidad).to.be.above(0);
    });
});

pm.test("El checkout se realiza correctamente", function () {
    pm.response.to.have.status(200);
});

pm.test("La compra devuelve un mensaje de confirmación", function () {
    const respuesta = pm.response.json();

    pm.expect(respuesta.mensaje).to.eql(
        "Compra realizada correctamente. Pago simulado."
    );
});

pm.test("El pedido queda registrado como pagado", function () {
    const respuesta = pm.response.json();

    pm.expect(respuesta.pedido.estado).to.eql("pagado");
    pm.expect(respuesta.pedido.metodoPago).to.eql("simulado");
    pm.expect(respuesta.pedido.total).to.be.a("number");
});
